import{_ as c,r as n,o as r,c as i,e as t,a,s as o,d as e}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"Страницы ( Pages ) - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Введение","slug":"введение","link":"#введение","children":[]},{"level":2,"title":"Настройка страницы","slug":"настроика-страницы","link":"#настроика-страницы","children":[{"level":3,"title":"Синтаксис URL","slug":"синтаксис-url","link":"#синтаксис-url","children":[]}]},{"level":2,"title":"Динамические страницы","slug":"динамические-страницы","link":"#динамические-страницы","children":[{"level":3,"title":"Жизненный цикл страницы","slug":"жизненныи-цикл-страницы","link":"#жизненныи-цикл-страницы","children":[]},{"level":3,"title":"Произвольный ответ","slug":"произвольныи-ответ","link":"#произвольныи-ответ","children":[]},{"level":3,"title":"Обработка форм","slug":"обработка-форм","link":"#обработка-форм","children":[]}]},{"level":2,"title":"Страница 404","slug":"страница-404","link":"#страница-404","children":[]},{"level":2,"title":"Страница ошибки","slug":"страница-ошибки","link":"#страница-ошибки","children":[]},{"level":2,"title":"Переменные страницы","slug":"переменные-страницы","link":"#переменные-страницы","children":[]},{"level":2,"title":"Добавление стилей и скриптов на страницу","slug":"добавление-стилеи-и-скриптов-на-страницу","link":"#добавление-стилеи-и-скриптов-на-страницу","children":[]}],"relativePath":"1.x/ru/cms/pages.md","filePath":"1.x/ru/cms/pages.md"}'),d={name:"1.x/ru/cms/pages.md"};function u(g,s,h,m,k,v){const l=n("pre-heading"),p=n("post-heading");return r(),i("div",null,[t(l),s[0]||(s[0]=a("h1",null,"Страницы ( Pages )",-1)),t(p),s[1]||(s[1]=o(`<p><a name="introduction"></a></p><h2 id="введение"><a href="#введение" class="header-anchor">#</a> Введение</h2><p>Все сайты имеют страницы. В OctoberCMS страницы представлены в виде шаблонов. Шаблоны страниц находятся в папке с темой в подпапке <strong>/pages</strong>. Название файлов не влияет на путь до страницы. Файлы должны иметь расширение <strong>htm</strong>. <a href="./../cms/themes.html#configuration-section">Раздел Конфигурации</a> и <a href="./../cms/themes.html#twig-section">Twig разметки</a> являются обязательными для использования при создании и редактировании страниц, в то время как <a href="./../cms/themes.html#php-section">Раздел PHP кода</a> - нет. Ниже представлен пример Главной страницы.</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;/&quot;
==
&lt;h1&gt;Hello, world!&lt;/h1&gt;
</code></pre></div><p><a name="configuration"></a></p><h2 id="настроика-страницы"><a href="#настроика-страницы" class="header-anchor">#</a> Настройка страницы</h2><p>Блок с настройками страницы находится в <a href="./../cms/themes.html#configuration-section">Разделе Конфигурации</a>. Здесь задаются параметры страницы, которые необходимы для маршрутизации, отображения самой страницы и ее <a href="./../cms/components.html">Компонентов</a>. Пример:</p><div class="table"><table tabindex="0"><thead><tr><th>Параметр</th><th>Описание</th></tr></thead><tbody><tr><td><strong>url</strong></td><td>URL страницы, обязателен. Синтаксис описан ниже.</td></tr><tr><td><strong>title</strong></td><td>заголовок страницы, обязателен.</td></tr><tr><td><strong>layout</strong></td><td><a href="./../cms/layouts.html">макет</a> страницы. Если указан, то должен содержать название файла без расширения. Например: <code>default</code>.</td></tr><tr><td><strong>description</strong></td><td>описание страницы для административной части сайта, необязательный.</td></tr></tbody></table></div><p><a name="url-syntax"></a></p><h3 id="синтаксис-url"><a href="#синтаксис-url" class="header-anchor">#</a> Синтаксис URL</h3><p>Адрес страницы определяется параметром <strong>url</strong> и должен начинаться с <code>/</code>. Ниже представлен пример страницы с адресом <code>/blog</code>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
</code></pre></div><p>Также в URL можно указать аргументы (шаблоны), которые могут использовать компоненты или сами страницы в <a href="./../cms/themes.html#php-section">разделе PHP кода</a>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/post/:post_id</span>&quot;</span>
</code></pre></div><p>Пример получения аргумента в PHP секции (см. <a href="#dynamic-pages">Динамические страницы</a>):</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;/blog/post/:post_id&quot;
==
function onStart()
{
    $post_id = $this-&gt;param(&#39;post_id&#39;);
}
==
</code></pre></div><p>Имена аргументов должны быть совместимы с именами PHP переменных. Чтобы сделать параметр необязательным, добавьте после него <code>?</code>:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/post/:post_id?</span>&quot;</span>
</code></pre></div><p>Аргументы в середине URL <strong>не могут быть</strong> необязательными.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:post_id?/comments</span>&quot;</span>
</code></pre></div><p>Необязательные аргументы могут иметь значения по умолчанию, которые могут быть использованы вместо обязательных параметров. Они задаются после вопросительного знака <code>?</code>. Значения по умолчанию не могут содержать <code>|</code> или <code>?</code>. В следующем примере аргумент <code>category_id</code> будет равен <code>10</code> для <code>/blog/category</code>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/category/:category_id?10</span>&quot;</span>
</code></pre></div><p>Вы также можете использовать в URL регулярные выражения. После названия параметра добавьте <code>|</code> и необходимое выражение (использовать <code>/</code> в выражении запрещено). Примеры:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;/blog/:post_id|^[0-9]+$/comments&quot; - this will match /blog/post/10/comments</span>
<span class="token comment">;...</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;/blog/:post_id|^[0-9]+$&quot; - this will match /blog/post/3</span>
<span class="token comment">;...</span>
<span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;/blog/:post_name?|^[a-z0-9\\-]+$&quot; - this will match /blog/my-blog-post</span>
</code></pre></div><p>Допустимо использование <em>подстановочных</em> аргументов путем добавления * после его названия.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:category*/:slug</span>&quot;</span>
</code></pre></div><p>Например: <code>/color/:color/make/:make*/edit</code> ---&gt; <code>/color/brown/make/volkswagen/beetle/retro/edit</code>. Тогда будут доступны следующие параметры:</p><div class="language- extra-class"><pre class="language-text"><code>- color: \`brown\`
- make: \`volkswagen/beetle/retro\`
</code></pre></div><blockquote><p><strong>Примечание:</strong> URL страницы определяются только параметром <strong>url</strong>.</p></blockquote><p><a name="dynamic-pages"></a></p><h2 id="динамические-страницы"><a href="#динамические-страницы" class="header-anchor">#</a> Динамические страницы</h2>`,31)),s[2]||(s[2]=a("p",null,[e("Вы можете использовать любые нативные "),a("a",{href:"https://twig.symfony.com/doc/",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[e("Twig"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),e(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),e(),a("span",{class:"sr-only"},"(opens new window)")])]),e(" функции, фильтры и теги внутри "),a("a",{href:"./../cms/themes.html#twig-section"},"Раздела Twig разметки"),e(". Любая динамическая страница использует "),a("strong",null,"переменные"),e(". Переменные определяются либо в "),a("a",{href:"./../cms/themes.html#php-section"},"Разделе PHP кода"),e(", либо "),a("a",{href:"./../cms/components.html"},"Компонентами"),e(". В этом разделе мы опишем, как инициализировать переменные в PHP секции.")],-1)),s[3]||(s[3]=o(`<p><a name="page-life-cycle"></a></p><h3 id="жизненныи-цикл-страницы"><a href="#жизненныи-цикл-страницы" class="header-anchor">#</a> Жизненный цикл страницы</h3><p>Существуют специальные функции, которые могут быть определены в Разделе PHP кода на странице или макета: <code>onInit()</code>, <code>onStart()</code> и <code>onEnd()</code>. Функция <code>onInit()</code> выполняется, когда все компоненты были инициализированы, но перед обработкой AJAX запросов. Функция <code>onStart()</code> выполняется в начале загрузки страницы. <code>onEnd()</code> - перед отображением страницы, но после работы <a href="./../cms/components.html">компонентов</a>. В функциях onStart и onEnd Вы можете определить переменные, которые потом можно использовать в <a href="./../cms/themes.html#twig-section">Разделе Twig разметки</a>.</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;/&quot;
==
function onStart()
{
    $this[&#39;hello&#39;] = &quot;Hello world!&quot;;
}
==
&lt;h3&gt;{{ hello }}&lt;/h3&gt;
</code></pre></div><p>Следующий пример посложнее. Он показывает, как загрузить на странице блога коллекцию из базы данных и отобразить ее на странице.</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;/blog&quot;
==
use Acme\\Blog\\Classes\\Post;

function onStart()
{
    $this[&#39;posts&#39;] = Post::orderBy(&#39;created_at&#39;, &#39;desc&#39;)-&gt;get();
}
==
&lt;h2&gt;Latest posts&lt;/h2&gt;
&lt;ul&gt;
    {% for post in posts %}
        &lt;h3&gt;{{ post.title }}&lt;/h3&gt;
        {{ post.content }}
    {% endfor %}
&lt;/ul&gt;
</code></pre></div><p>Переменные по умолчанию и &quot;Twig extensions&quot; описаны на странице <a href="./../cms/markup.html">Разметка</a>. Общяя последовательность вызовов обработчиков описана в параграфе <a href="./../cms/layouts.html#dynamic-layouts">Динамические макеты</a>.</p><p><a name="life-cycle-response"></a></p><h3 id="произвольныи-ответ"><a href="#произвольныи-ответ" class="header-anchor">#</a> Произвольный ответ</h3><p>Все методы, определенные в жизненном цикле страницы, имеют возможность остановить процесс загрузки и вернуть произвольный ответ. Приведенный ниже пример не будет загружать содержимое страницы и вернет только строку * Hello World * :</p><pre><code>function onStart()
{
    return &#39;Hello world!&#39;;
}
</code></pre><p>Более полезным примером может быть использование редиректа:</p><pre><code>public function onStart()
{
    return Redirect:to(&#39;http://google.com&#39;);
}
</code></pre><p><a name="handling-forms"></a></p><h3 id="обработка-форм"><a href="#обработка-форм" class="header-anchor">#</a> Обработка форм</h3><p>Вы можете управлять стандартными формами при помощи методов-обработчиков, определенных в <a href="./../cms/themes.html#php-section">Разделе PHP кода</a> страницы или шаблона (обработка AJAX запросов объясняется на странице <a href="./../cms/ajax.html">AJAX</a>). Используйте <a href="./../cms/markup.html#standard-form">form_open()</a>, чтобы создать форму с обработчиком <code>onHandleForm</code>. Пример:</p><div class="language- extra-class"><pre class="language-text"><code>{{ form_open({ request: &#39;onHandleForm&#39; }) }}
    Please enter a string: &lt;input type=&quot;text&quot; name=&quot;value&quot;/&gt;
    &lt;input type=&quot;submit&quot; value=&quot;Submit me!&quot;/&gt;
{{ form_close() }}
&lt;p&gt;Last submitted value: {{ lastValue }}&lt;/p&gt;
</code></pre></div><p>Функцию onHandleForm можно определить в <a href="./../cms/themes.html#php-section">PHP секции</a> шаблона или страницы:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onHandleForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;lastValue&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Обработчик получает переменную <code>value</code> при помощи функции <code>post()</code> и инициализирует переменную <code>lastValue</code>, которая выводится после формы в предыдущем примере.</p><blockquote><p><strong>Примечание:</strong> Если существуют обработчики с одинаковыми названиями в компоненте, шаблоне и странице, то выполнен будет тот, который определен на странице.</p></blockquote><p>Если Вы хотите обратиться к определенному обработчику в конкретном <a href="./../cms/components.html">компоненте</a>, то используйте имя компонента или псевдоним в ссылке на обработчик:</p><div class="language- extra-class"><pre class="language-text"><code>{{ form_open({ request: &#39;myComponent::onHandleForm&#39; }) }}
</code></pre></div><p><a name="404-page"></a></p><h2 id="страница-404"><a href="#страница-404" class="header-anchor">#</a> Страница 404</h2><p>Если тема содержит страницу с URL <code>/404</code>, то она будет отображаться вместо ненайденной страницы.</p><p><a name="error-page"></a></p><h2 id="страница-ошибки"><a href="#страница-ошибки" class="header-anchor">#</a> Страница ошибки</h2><p>При возникновении ошибки на странице будет показано ее подробное описание. Вы можете отобразить свою страницу, изменив значение <code>debug</code> на <strong>false</strong> в файле <code>app/config/cms.php</code> и создав страницу с URL <code>/error</code>.</p><p><a name="page-variables"></a></p><h2 id="переменные-страницы"><a href="#переменные-страницы" class="header-anchor">#</a> Переменные страницы</h2><p>Вы можете изменить переменные страницы в <a href="./../cms/themes.html#php-section">PHP секции</a> или <a href="./../cms/components.html">Компоненте</a>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onEnd</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token operator">-&gt;</span><span class="token property">title</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;A different page title&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Также вы можете использовать их на странице, используя переменную <a href="./../markup/this-page.html"><code>this.page</code></a>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>The title of this page is: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> this<span class="token punctuation">.</span>page<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><a name="injecting-assets"></a></p><h2 id="добавление-стилеи-и-скриптов-на-страницу"><a href="#добавление-стилеи-и-скриптов-на-страницу" class="header-anchor">#</a> Добавление стилей и скриптов на страницу</h2><p>Вы можете добавить стили и скрипты на страницу при помощи методов <code>addCss()</code> и <code>addJs()</code> соответственно. Разместить эти методы можно в функции <code>onStart()</code>, которая определяется в <a href="./../cms/themes.html#php-section">PHP секции</a> страницы или шаблона. Пример:</p><pre><code>function onStart()
{
    $this-&gt;addCss(&#39;assets/css/hello.css&#39;);
    $this-&gt;addJs(&#39;assets/js/app.js&#39;);
}
</code></pre><p>Если в начале пути до файла указан <code>/</code>, то он будет определен относительно папки с сайтом. В противном случае - относительно папки с темой.</p><p>Но лучше использовать теги <a href="./../cms/markup.html#styles-tag">{% styles %}</a> и <a href="./../cms/markup.html#scripts-tag">{% scripts %}</a>. Пример:</p><div class="language- extra-class"><pre class="language-text"><code>&lt;head&gt;
    ...
    {% styles %}
&lt;/head&gt;
&lt;body&gt;
    ...
    {% scripts %}
&lt;/body&gt;
</code></pre></div>`,42))])}const q=c(d,[["render",u]]);export{_ as __pageData,q as default};
